SELECT s."sname", s."avgscrread", sc."rtype", sc."cds", c."school", c."mailstreet", c."mailstrabr", c."mailcity", c."mailstate", c."mailzip", c."doc", c."soctype", c."district"
FROM "satscores" sc JOIN "schools" c ON c."cdscode" = sc."cds"
WHERE c."doc" = '31' ORDER BY sc."avgscrread" DESC NULLS LAST;

SELECT sc."sname", sc."avgscrread", sc."rtype", sc."cds", c."school", c."mailstreet", c."mailstrabr", c."mailcity", c."mailstate", c."mailzip", c."doc", c."soctype", c."district"
FROM "satscores" sc JOIN "schools" c ON c."cdscode" = sc."cds"
WHERE c."doc" = '31' ORDER BY sc."avgscrread" DESC NULLS LAST;

SELECT COUNT(*) AS total_single_comment_posts_rows
FROM (SELECT postid FROM comments GROUP BY postid HAVING COUNT(*) = 1) s
JOIN posts p ON p.id = s.postid;

SELECT COUNT(*) AS total_matching, SUM(CASE WHEN c.score = 0 THEN 1 ELSE 0 END) AS zero_score, SUM(CASE WHEN c.score IS NULL THEN 1 ELSE 0 END) AS null_score
FROM comments c
JOIN posts p ON p.id = c.postid
WHERE c.postid IN (
  SELECT postid FROM comments GROUP BY postid HAVING COUNT(*) = 1
);

WITH de AS (SELECT id FROM users WHERE location ILIKE '%germany%')
SELECT b.userid, b.name, b.date FROM badges b JOIN de ON de.id=b.userid
WHERE b.userid IN (SELECT b2.userid FROM badges b2 WHERE b2.name='Organizer') ORDER BY b.userid, b.date LIMIT 20;
